import math

def normal_cdf(x):
    return 0.5*math.erfc(-x/math.sqrt(2.0))

def european_pair(spot,strike,rate,years,vol):
    # No dividends,European exercise,continuous annual rate and annualized vol.
    for value,low,high in ((spot,1.0,10000.0),(strike,1.0,10000.0),(rate,-0.2,0.5),(years,0.0,10.0),(vol,0.0,2.0)):
        if type(value) is not float or not math.isfinite(value) or not low<=value<=high:
            raise ValueError("invalid bounded pricing input")
    if years==0.0:return max(spot-strike,0.0),max(strike-spot,0.0)
    discounted_strike=strike*math.exp(-rate*years)
    if vol==0.0:return max(spot-discounted_strike,0.0),max(discounted_strike-spot,0.0)
    if years<1e-6 or vol<1e-6:
        raise ValueError("positive time/vol below teaching numerical domain")
    width=vol*math.sqrt(years)
    d1=(math.log(spot/strike)+(rate+0.5*vol*vol)*years)/width
    d2=d1-width
    if max(abs(d1),abs(d2))>8.0:
        raise ValueError("normal tail outside teaching numerical domain")
    # Compute the out-of-money side directly,then parity for the other side.
    if spot<=discounted_strike:
        call=spot*normal_cdf(d1)-discounted_strike*normal_cdf(d2)
        put=call+discounted_strike-spot
    else:
        put=discounted_strike*normal_cdf(-d2)-spot*normal_cdf(-d1)
        call=put+spot-discounted_strike
    return call,put

call,put=european_pair(100.0,100.0,0.05,1.0,0.2)
print(f"{call:.6f} {put:.6f}")
print(european_pair(120.0,100.0,0.05,0.0,0.2))
print(european_pair(100.0,100.0,0.0,1.0,0.0))
zero=european_pair(100.0,100.0,0.05,1.0,0.0)
print(f"{zero[0]:.6f} {zero[1]:.6f}")
try:european_pair(100.0,100.0,0.05,1.0,-0.2)
except ValueError as error:print(error)
